// PipeName is retained for descriptor uniformity, but BitsPeerAuth is NOT a named-pipe
// interface: per [MS-BPAU] 2.1 the protocol is carried over ncacn_ip_tcp on a dynamic
// endpoint that the client resolves through the endpoint mapper (TCP/135), and the
// server registers the Kerberos security provider (RPC authentication is mandatory).
// This constant is not the standard binding for this interface.
const PipeName = `\bpau`

// Opnums for the on-the-wire methods.
const (
	OpnumExchangePublicKeys uint16 = 0
)

// ExchangePublicKeys returns an HRESULT ([MS-BPAU] 3.2.4.1, [MS-ERREF] 2.1): zero is
// success and any value with the severity bit set is a failure. Those values are not
// declared here, because the whole of [MS-ERREF] 2.1.1 lives in
// github.com/TheManticoreProject/Manticore/windows/errors/hresult as the HRESULT type.
// Convert a returned status with hresult.HRESULT(status) and compare against
// hresult.S_OK; hresult.HRESULT.IsSuccess covers the whole success range, since for an
// HRESULT success is a severity bit rather than the single value zero. The value
// [MS-BPAU] 3.2.4.1 gives for an untrusted caller, 0x80070005, is E_ACCESSDENIED there
// and needs no declaration.
//
// The one value that stays local is the exception, and it is a facility collision rather
// than an oversight. [MS-BPAU] 3.2.4.1 says only "the server MUST return 0x80040006" when
// the peer-certificate table is full, giving that value no symbolic name; the shared table
// names the same value OLE_E_NOCACHE, "There is no cache to operate on", which is a
// different protocol's meaning entirely. Both are legitimate: 0x80040006 is in facility 4,
// FACILITY_ITF, the interface-specific range that [MS-ERREF] 2.1 leaves to whichever
// interface returns the value, and the shared table fills it with the 283 OLE and
// drag-drop names COM assigns there. So StatusString decodes this one itself and defers
// every other value to the shared table.
const (
	// StatusTableFull is returned when the server's peer-certificate table has reached
	// its implementation-specific size limit ([MS-BPAU] 3.2.4.1). The specification gives
	// it no name; the shared [MS-ERREF] 2.1.1 table calls this value OLE_E_NOCACHE, an
	// unrelated FACILITY_ITF assignment, which is why it is not resolved through it.
	StatusTableFull uint32 = 0x80040006
)

// SyntaxID returns the BitsPeerAuth abstract syntax identifier:
// e3d0d746-d2af-40fd-8a7a-0d7078bb7092, version 1.0.
func SyntaxID() syntax.SyntaxID {
	return syntax.SyntaxID{
		UUID:         guid.GUID{A: 0xe3d0d746, B: 0xd2af, C: 0x40fd, D: 0x8a7a, E: 0x0d7078bb7092},
		MajorVersion: 1,
		MinorVersion: 0,
	}
}

// StatusString decodes the one status whose value [MS-ERREF] 2.1.1 assigns to an
// unrelated FACILITY_ITF name, and defers every other status to the shared [MS-ERREF]
// 2.1.1 table, which names each value the specification defines and renders hex only for
// values it does not.
func StatusString(status uint32) string {
	switch status {
	case StatusTableFull:
		return "0x80040006 (peer-certificate table full)"
	default:
		return hresult.HRESULT(status).String()
	}
}

